1	import { X, Sparkles } from "lucide-react";
2	import { Button } from "@/components/ui/button";
3	import { useRediscoveredCandidates } from "@/hooks/useRediscovery";
4	
5	interface RediscoveryBannerProps {
6	  jobId: string;
7	  onViewCandidates: () => void;
8	  onDismiss: () => void;
9	}
10	
11	/**
12	 * Dismissible banner shown at the top of the results section when past candidates
13	 * match the current job's JD via vector similarity.
14	 * Auto-hides when there are no matches or data is still loading.
15	 */
16	const RediscoveryBanner = ({ jobId, onViewCandidates, onDismiss }: RediscoveryBannerProps) => {
17	  const { data: candidates, isLoading } = useRediscoveredCandidates(jobId);
18	
19	  // Don't render anything until we know there are matches
20	  if (isLoading || !candidates || candidates.length === 0) return null;
21	
22	  const count = candidates.length;
23	
24	  return (
25	    <div
26	      className="flex items-center justify-between gap-3 rounded-lg border border-primary/30 bg-primary/5 px-4 py-3 animate-fade-in"
27	      role="status"
28	      aria-live="polite"
29	    >
30	      <div className="flex items-center gap-3 min-w-0">
31	        <Sparkles className="h-4 w-4 shrink-0 text-primary" aria-hidden="true" />
32	        <p className="text-sm font-medium text-foreground leading-snug">
33	          <span className="text-primary">{count}</span>{" "}
34	          past candidate{count !== 1 ? "s" : ""} match this role
35	        </p>
36	        <p className="text-sm text-muted-foreground hidden sm:block">
37	          — Rediscovered from your talent history
38	        </p>
39	      </div>
40	
41	      <div className="flex items-center gap-2 shrink-0">
42	        <Button
43	          size="sm"
44	          variant="default"
45	          className="h-7 text-xs gap-1.5"
46	          onClick={onViewCandidates}
47	        >
48	          View {count > 1 ? `all ${count}` : "candidate"}
49	        </Button>
50	        <button
51	          onClick={onDismiss}
52	          className="rounded p-1 text-muted-foreground hover:text-foreground hover:bg-muted/60 transition-colors"
53	          aria-label="Dismiss rediscovery banner"
54	        >
55	          <X className="h-3.5 w-3.5" />
56	        </button>
57	      </div>
58	    </div>
59	  );
60	};
61	
62	export default RediscoveryBanner;
