1	import { useState } from "react";
2	import { Sparkles, Loader2, CheckCircle2, Briefcase, TrendingUp } from "lucide-react";
3	import {
4	  Dialog,
5	  DialogContent,
6	  DialogHeader,
7	  DialogTitle,
8	  DialogDescription,
9	} from "@/components/ui/dialog";
10	import { Button } from "@/components/ui/button";
11	import { Badge } from "@/components/ui/badge";
12	import { Skeleton } from "@/components/ui/skeleton";
13	import { useRediscoveredCandidates, useImportRediscovered } from "@/hooks/useRediscovery";
14	import type { RediscoveredCandidate } from "@/hooks/useRediscovery";
15	
16	// ─── Similarity badge colour ──────────────────────────────────────────────────
17	
18	function similarityVariant(pct: number): "default" | "secondary" | "outline" {
19	  if (pct >= 80) return "default";
20	  if (pct >= 70) return "secondary";
21	  return "outline";
22	}
23	
24	// ─── Candidate row ────────────────────────────────────────────────────────────
25	
26	interface CandidateItemProps {
27	  candidate: RediscoveredCandidate;
28	  selected: boolean;
29	  imported: boolean;
30	  onToggle: (id: string) => void;
31	}
32	
33	function CandidateItem({ candidate, selected, imported, onToggle }: CandidateItemProps) {
34	  return (
35	    <div
36	      className={`flex items-center gap-3 rounded-lg border p-3 cursor-pointer transition-colors ${
37	        imported
38	          ? "border-border bg-muted/30 opacity-60 cursor-not-allowed"
39	          : selected
40	          ? "border-primary/60 bg-primary/5"
41	          : "border-border hover:border-primary/30 hover:bg-muted/30"
42	      }`}
43	      onClick={() => !imported && onToggle(candidate.resume_id)}
44	      role="checkbox"
45	      aria-checked={selected}
46	      aria-disabled={imported}
47	      tabIndex={imported ? -1 : 0}
48	      onKeyDown={(e) => {
49	        if (!imported && (e.key === " " || e.key === "Enter")) {
50	          e.preventDefault();
51	          onToggle(candidate.resume_id);
52	        }
53	      }}
54	    >
