24	/** Send a single email via Resend */
25	async function sendViaResend(
26	  apiKey: string,
27	  from: { email: string; name: string },
28	  to: string,
29	  subject: string,
30	  htmlContent: string
31	): Promise<{ ok: boolean; resendId: string | null; errorMessage: string | null }> {
32	  const res = await fetch("https://api.resend.com/emails", {
33	    method: "POST",
34	    headers: {
35	      Authorization: `Bearer ${apiKey}`,
36	      "Content-Type": "application/json",
37	    },
38	    body: JSON.stringify({
39	      from: `${from.name} <${from.email}>`,
40	      to: [to],
41	      subject,
42	      html: htmlContent,
43	    }),
44	  });
45	
46	  const body = await res.text();
47	
48	  if (!res.ok) {
49	    let errorMessage = `Resend error status=${res.status}`;
50	    try {
51	      const parsed = JSON.parse(body);
52	      errorMessage = parsed.message || parsed.error?.message || errorMessage;
53	    } catch { /* ignore */ }
54	    return { ok: false, resendId: null, errorMessage };
55	  }
56	
57	  let resendId: string | null = null;
58	  try {
59	    const parsed = JSON.parse(body);
60	    resendId = parsed.id ?? null;
61	  } catch { /* ignore */ }
62	
63	  return { ok: true, resendId, errorMessage: null };
64	}
