124	        scheduled_for,
125	        enrollment_id,
126	        step_id,
127	        sequence_steps (
128	          subject,
129	          body,
130	          step_order,
131	          sequence_id
132	        ),
133	        sequence_enrollments (
134	          id,
135	          status,
136	          resume_id,
137	          job_id,
138	          enrolled_by,
139	          resumes (
140	            candidate_name,
141	            candidate_email
