206	      const bodyHtml = renderTemplate(
207	        step.body.replace(/\n/g, "<br>"),
208	        variables
209	      );
210	
211	      try {
212	        const result = await sendViaResend(
213	          config.resend_api_key,
214	          { email: fromEmail, name: variables.recruiter_name || fromName },
215	          candidateEmail,
216	          subject,
217	          bodyHtml
218	        );
219	
220	        if (result.ok) {
221	          await supabase
222	            .from("sequence_sends")
223	            .update({
224	              status: "sent",
225	              sent_at: new Date().toISOString(),
226	              resend_id: result.resendId,
227	              error: null,
228	            })
229	            .eq("id", send.id);
230	          sent++;
231	        } else {
232	          await supabase
233	            .from("sequence_sends")
234	            .update({ status: "failed", error: result.errorMessage })
235	            .eq("id", send.id);
236	          failed++;
237	
238	          await logSystemError({
239	            function_name: "send-sequence-step",
240	            error_type: "RESEND_ERROR",
241	            severity: "warning",
242	            error_message: result.errorMessage ?? "Unknown Resend error",
243	            user_id: enrollment.enrolled_by,
244	          });
245	        }
246	      } catch (sendErr: unknown) {
247	        const msg = errorToMessage(sendErr);
248	        await supabase
249	          .from("sequence_sends")
250	          .update({ status: "failed", error: msg })
251	          .eq("id", send.id);
252	        failed++;
253	        console.error(`send-sequence-step send error for send ${send.id}:`, msg);
254	      }
255	    }
256	
257	    // Mark completed enrollments (all sends done)
258	    // Find enrollments where all sends are no longer pending
259	    const enrollmentIds = [...new Set(pendingSends.map((s) => s.enrollment_id))];
260	    for (const enrollmentId of enrollmentIds) {
261	      const { count } = await supabase
262	        .from("sequence_sends")
263	        .select("*", { count: "exact", head: true })
264	        .eq("enrollment_id", enrollmentId)
265	        .eq("status", "pending");
266	
267	      if ((count ?? 0) === 0) {
268	        await supabase
269	          .from("sequence_enrollments")
270	          .update({ status: "completed", completed_at: new Date().toISOString() })
271	          .eq("id", enrollmentId)
272	          .eq("status", "active");
273	      }
274	    }
275	
276	    return new Response(
277	      JSON.stringify({ processed: pendingSends.length, sent, failed, skipped }),
278	      { status: 200, headers: { "Content-Type": "application/json" } }
279	    );
280	  } catch (err: unknown) {
281	    console.error("send-sequence-step error:", err);
282	    await logSystemError({
283	      function_name: "send-sequence-step",
284	      error_type: "CRON_ERROR",
285	      severity: "error",
286	      error_message: errorToMessage(err),
287	    });
288	    return new Response(
289	      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
290	      { status: 500, headers: { "Content-Type": "application/json" } }
291	    );
292	  }
293	});
