131	/** Single sequence with its steps */
132	export function useSequence(id: string | null) {
133	  const { user } = useAuth();
134	
135	  return useQuery<Sequence | null>({
136	    queryKey: qk.sequence(id ?? "__none__"),
137	    queryFn: async () => {
138	      if (!id) return null;
139	      const { data, error } = await (supabase as any)
140	        .from("sequences")
141	        .select(`
142	          id, user_id, team_id, name, description, is_active, created_at, updated_at,
143	          sequence_steps (
144	            id, sequence_id, step_order, day_offset, subject, body, created_at
145	          )
146	        `)
147	        .eq("id", id)
148	        .single();
149	
150	      if (error) throw error;
151	
152	      return {
153	        ...data,
154	        sequence_steps: (data?.sequence_steps ?? []).sort(
155	          (a: SequenceStep, b: SequenceStep) => a.step_order - b.step_order
156	        ),
157	      };
158	    },
159	    enabled: !!user && !!id,
160	    staleTime: 60_000,
161	  });
