172	
173	      const { data, error } = await (supabase as any)
174	        .from("sequence_enrollments")
175	        .select(`
176	          id, sequence_id, resume_id, job_id, enrolled_by, status, enrolled_at, completed_at,
177	          resumes ( candidate_name, candidate_email ),
178	          jobs ( title ),
179	          sends:sequence_sends (
180	            id, enrollment_id, step_id, scheduled_for, sent_at, status, error, resend_id, created_at
