277	
278	interface SequenceBuilderProps {
279	  open: boolean;
280	  onOpenChange: (open: boolean) => void;
281	  /** If provided, we're editing an existing sequence; otherwise creating new */
282	  sequenceId?: string | null;
283	  onSaved?: (id: string) => void;
284	}
285	
286	export function SequenceBuilder({
287	  open,
288	  onOpenChange,
289	  sequenceId,
290	  onSaved,
291	}: SequenceBuilderProps) {
292	  const isEditing = !!sequenceId;
293	
294	  const { data: existing, isLoading: loadingExisting } = useSequence(
295	    open && isEditing ? sequenceId : null
296	  );
297	
298	  const createSequence = useCreateSequence();
299	  const updateSequence = useUpdateSequence();
300	  const addStep = useAddSequenceStep();
301	  const updateStep = useUpdateSequenceStep();
302	  const deleteStep = useDeleteSequenceStep();
303	
304	  const [name, setName] = useState("");
305	  const [description, setDescription] = useState("");
306	  const [steps, setSteps] = useState<LocalStep[]>([]);
307	  const [deletingIndex, setDeletingIndex] = useState<number | null>(null);
308	  const [isSaving, setIsSaving] = useState(false);
309	
310	  // Populate form when editing
311	  useEffect(() => {
312	    if (open && isEditing && existing) {
313	      setName(existing.name);
314	      setDescription(existing.description ?? "");
315	      setSteps(
316	        (existing.sequence_steps ?? []).map((s: SequenceStep) => ({
317	          id: s.id,
318	          step_order: s.step_order,
319	          day_offset: s.day_offset,
320	          subject: s.subject,
321	          body: s.body,
322	        }))
323	      );
324	    }
325	  }, [open, isEditing, existing]);
326	
327	  // Reset when creating new
328	  useEffect(() => {
329	    if (open && !isEditing) {
330	      setName("");
331	      setDescription("");
332	      setSteps([
333	        { step_order: 1, day_offset: 0, subject: "", body: "" },
334	      ]);
335	    }
336	  }, [open, isEditing]);
337	
338	  function handleStepChange(index: number, field: keyof LocalStep, value: string | number) {
339	    setSteps((prev) => {
340	      const next = [...prev];
341	      next[index] = { ...next[index], [field]: value };
342	      return next;
343	    });
344	  }
345	
346	  function handleAddStep() {
347	    const maxOffset = steps.reduce((m, s) => Math.max(m, s.day_offset), 0);
348	    setSteps((prev) => [
349	      ...prev,
350	      {
351	        step_order: prev.length + 1,
352	        day_offset: maxOffset + 3,
353	        subject: "",
354	        body: "",
355	      },
356	    ]);
357	  }
358	
359	  function handleMoveStep(index: number, direction: "up" | "down") {
360	    setSteps((prev) => {
361	      const next = [...prev];
362	      const targetIndex = direction === "up" ? index - 1 : index + 1;
363	      if (targetIndex < 0 || targetIndex >= next.length) return prev;
364	      [next[index], next[targetIndex]] = [next[targetIndex], next[index]];
365	      // Re-number
366	      return next.map((s, i) => ({ ...s, step_order: i + 1 }));
367	    });
368	  }
369	
370	  async function handleDeleteStep(index: number) {
371	    const step = steps[index];
372	    setDeletingIndex(index);
373	    try {
374	      if (step.id && sequenceId) {
375	        await deleteStep.mutateAsync({ id: step.id, sequence_id: sequenceId });
376	      }
377	      setSteps((prev) => {
378	        const next = prev.filter((_, i) => i !== index);
379	        return next.map((s, i) => ({ ...s, step_order: i + 1 }));
380	      });
381	    } catch {
382	      toast.error("Failed to delete step");
383	    } finally {
384	      setDeletingIndex(null);
385	    }
386	  }
387	
388	  async function handleSave() {
389	    if (!name.trim()) {
390	      toast.error("Sequence name is required");
391	      return;
392	    }
393	    if (steps.length === 0) {
394	      toast.error("Add at least one step");
395	      return;
396	    }
397	    const invalidStep = steps.find((s) => !s.subject.trim() || !s.body.trim());
398	    if (invalidStep) {
399	      toast.error(`Step ${invalidStep.step_order}: subject and body are required`);
400	      return;
401	    }
402	
403	    setIsSaving(true);
404	    try {
405	      let savedId: string;
406	
407	      if (isEditing && sequenceId) {
408	        await updateSequence.mutateAsync({
409	          id: sequenceId,
410	          name: name.trim(),
411	          description: description.trim() || undefined,
412	        });
413	        savedId = sequenceId;
414	
415	        // Upsert steps — update existing, insert new
416	        for (const step of steps) {
417	          if (step.id) {
418	            await updateStep.mutateAsync({
419	              id: step.id,
420	              sequence_id: sequenceId,
421	              step_order: step.step_order,
422	              day_offset: step.day_offset,
423	              subject: step.subject.trim(),
424	              body: step.body.trim(),
425	            });
426	          } else {
427	            await addStep.mutateAsync({
428	              sequence_id: sequenceId,
429	              step_order: step.step_order,
430	              day_offset: step.day_offset,
431	              subject: step.subject.trim(),
432	              body: step.body.trim(),
433	            });
434	          }
435	        }
436	      } else {
437	        const created = await createSequence.mutateAsync({
438	          name: name.trim(),
439	          description: description.trim() || undefined,
440	        });
441	        savedId = created.id;
442	
443	        for (const step of steps) {
444	          await addStep.mutateAsync({
445	            sequence_id: savedId,
446	            step_order: step.step_order,
447	            day_offset: step.day_offset,
448	            subject: step.subject.trim(),
449	            body: step.body.trim(),
450	          });
451	        }
452	      }
453	
454	      toast.success(isEditing ? "Sequence updated" : "Sequence created");
455	      onSaved?.(savedId);
456	      onOpenChange(false);
457	    } catch (err: unknown) {
458	      toast.error(err instanceof Error ? err.message : "Failed to save sequence");
459	    } finally {
460	      setIsSaving(false);
461	    }
462	  }
463	
464	  const isLoading = isEditing && loadingExisting;
465	
466	  return (
467	    <Dialog open={open} onOpenChange={onOpenChange}>
468	      <DialogContent className="sm:max-w-2xl max-h-[90vh] overflow-hidden flex flex-col">
469	        <DialogHeader>
470	          <DialogTitle className="flex items-center gap-2">
471	            <Mail className="h-4 w-4" />
472	            {isEditing ? "Edit Sequence" : "New Email Sequence"}
473	          </DialogTitle>
474	        </DialogHeader>
475	
476	        {isLoading ? (
477	          <div className="flex items-center justify-center py-12">
478	            <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
479	          </div>
480	        ) : (
481	          <div className="flex-1 overflow-y-auto space-y-5 py-2 pr-1">
482	            {/* Name + description */}
483	            <div className="space-y-3">
484	              <div className="space-y-1.5">
485	                <Label htmlFor="seq-name">
486	                  Name <span className="text-destructive">*</span>
487	                </Label>
488	                <Input
489	                  id="seq-name"
490	                  value={name}
491	                  onChange={(e) => setName(e.target.value)}
492	                  placeholder="e.g. Engineering candidate outreach"
493	                  disabled={isSaving}
494	                />
495	              </div>
496	              <div className="space-y-1.5">
497	                <Label htmlFor="seq-desc">Description</Label>
498	                <Textarea
499	                  id="seq-desc"
500	                  value={description}
501	                  onChange={(e) => setDescription(e.target.value)}
502	                  placeholder="Optional — helps your team understand the purpose"
503	                  rows={2}
504	                  className="resize-none text-sm"
505	                  disabled={isSaving}
506	                />
507	              </div>
508	            </div>
509	
510	            <Separator />
511	
512	            {/* Steps */}
513	            <div className="space-y-3">
514	              <div className="flex items-center justify-between">
515	                <div>
516	                  <p className="text-sm font-medium">Email Steps</p>
517	                  <p className="text-xs text-muted-foreground">
518	                    Define the sequence of emails. Day 0 sends immediately on enrollment.
519	                  </p>
520	                </div>
521	                <Button
522	                  type="button"
523	                  variant="outline"
524	                  size="sm"
525	                  onClick={handleAddStep}
526	                  className="gap-1.5 shrink-0"
527	                  disabled={isSaving}
528	                >
529	                  <Plus className="h-3.5 w-3.5" />
530	                  Add Step
531	                </Button>
532	              </div>
533	
534	              {steps.length === 0 ? (
535	                <div className="flex flex-col items-center justify-center py-8 rounded-lg border-2 border-dashed border-border text-center">
536	                  <Mail className="h-8 w-8 text-muted-foreground/30 mb-2" />
537	                  <p className="text-sm text-muted-foreground">No steps yet</p>
538	                  <Button
539	                    type="button"
540	                    variant="ghost"
541	                    size="sm"
542	                    onClick={handleAddStep}
543	                    className="mt-2 gap-1.5"
544	                  >
545	                    <Plus className="h-3.5 w-3.5" />
546	                    Add first step
547	                  </Button>
548	                </div>
549	              ) : (
550	                <div className="space-y-2">
551	                  {steps.map((step, i) => (
552	                    <StepEditor
553	                      key={step.id ?? `new-${i}`}
554	                      step={step}
555	                      index={i}
556	                      totalSteps={steps.length}
557	                      onChange={handleStepChange}
558	                      onDelete={handleDeleteStep}
559	                      onMoveUp={(idx) => handleMoveStep(idx, "up")}
560	                      onMoveDown={(idx) => handleMoveStep(idx, "down")}
561	                      isDeleting={deletingIndex === i}
562	                    />
563	                  ))}
564	                </div>
565	              )}
566	            </div>
567	          </div>
568	        )}
569	
570	        <DialogFooter className="pt-2 gap-2">
571	          <Button
572	            variant="outline"
573	            onClick={() => onOpenChange(false)}
574	            disabled={isSaving}
575	          >
576	            Cancel
577	          </Button>
578	          <Button onClick={handleSave} disabled={isSaving || isLoading} className="gap-1.5">
579	            {isSaving && <Loader2 className="h-4 w-4 animate-spin" />}
580	            {isSaving ? "Saving…" : isEditing ? "Update Sequence" : "Create Sequence"}
581	          </Button>
582	        </DialogFooter>
583	      </DialogContent>
584	    </Dialog>
585	  );
586	}
587	
588	export default SequenceBuilder;
